# همزة الوصل بعد واو العطف أو فاء متّصلة لا تُحرَّك كتابةً: «وَالْمَسْهَا» لا «وَاِلْمَسْهَا» (الفحص المستقل A للبوابة: عشرون موضعاً في الوحدات الثلاث).
# تُطبَّق عند الكتابة على كل نصّ، وفي صيغتي المخاطبة إن جاءتا بعد الحرف: «وَ{اِلْمَسْ|اِلْمَسِي}» ← «وَ{الْمَسْ|الْمَسِي}»
import re
_WASL = re.compile(r'(?<=[وف]َ)ا[ِ\u064f]')
_WASL_G = re.compile(r'(?<=[وف]َ)\{([^{}|]*)\|([^{}]*)\}')
def wasl(t):
    if not isinstance(t, str): return t
    t = _WASL_G.sub(lambda m: '{' + re.sub(r'^ا[ِ\u064f]', 'ا', m.group(1)) + '|' + re.sub(r'^ا[ِ\u064f]', 'ا', m.group(2)) + '}', t)
    return _WASL.sub('ا', t)
def _walk(o): return {k: _walk(v) for k, v in o.items()} if isinstance(o, dict) else [_walk(v) for v in o] if isinstance(o, list) else wasl(o)
def dump(path, obj):
    obj = _walk(obj)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f: json.dump(obj, f, ensure_ascii=False, indent=1); f.write('\n')
if __name__ == '__main__':
    dump(OUT + '/strings/gen.json', GEN); dump(OUT + '/strings/labels.json', LABELS); dump(OUT + '/errors.json', ERR)
    print(len(L), 'gen lines;', sum(len(e.get('q', {})) for e in ERR.values()), 'error questions;', len(ERR), 'tags')
